def recenter_molecules(c):
 # Molecular scattering is defined about the geometrical center. Remove the
 # coordinate-gauge null mode before serializing at ObjCryst XML precision.
 for im in range(c.GetNbScatterer()):
  m=c.GetScatterer(im)
  if m.GetClassName()!='Molecule':continue
  xyz=np.array([[m.GetAtom(i).X,m.GetAtom(i).Y,m.GetAtom(i).Z] for i in range(m.GetNbAtoms())]);ctr=xyz.mean(axis=0)
  if np.linalg.norm(ctr)>1e-6:
   for i,v in enumerate(xyz-ctr):a=m.GetAtom(i);a.X,a.Y,a.Z=v

