 if r is None or m.GetClassName()!='Molecule':return 0
 n=r.GetNumAtoms()
 if coords is None or len(coords)<n:
  coords=np.array([[m.GetAtom(i).X,m.GetAtom(i).Y,m.GetAtom(i).Z] for i in range(n)])
