 a=np.zeros((len(p.GetPowderPatternX()),nref),dtype=np.float64)
 ret=_lib.bridge_matrix(d.int_ptr(),a.ctypes.data,*a.shape)
 if ret<0:raise RuntimeError('Profile matrix failed '+str(ret))
 return a
def set_obs(d,values):
