 # A loaded Le Bail cache can still point at calculated rather than extracted
 # intensities. Verify the actual fixed-profile bridge before using its covariance.
 for check in range(3):
  cp=np.asarray(d.GetPowderPatternCalc());ratio=np.linalg.norm(mat[:,:len(f0)]@f0-cp)/max(np.linalg.norm(cp),1e-30)
  if np.isfinite(ratio) and ratio<.005:break
  print('PAWLEY_CACHE_REPAIR',check,ratio,p.GetRw(),flush=True)
  d.ExtractLeBail(10);p.Prepare();p.FitScaleFactorForRw();mat=profile_matrix(p,d);f0=np.asarray(d.GetFhklObsSq())
 x=np.asarray(p.GetPowderPatternX());weight=np.asarray(p.GetLSQWeight(0));obs=np.asarray(p.GetPowderPatternObs());calc=np.asarray(p.GetPowderPatternCalc());compcalc=np.asarray(d.GetPowderPatternCalc());scale=np.dot(calc-p.GetPowderPatternComponent(1).GetPowderPatternCalc(),compcalc)/np.dot(compcalc,compcalc)
 background=calc-compcalc*scale
 n=min(len(weight),len(x));sel=np.arange(len(f0))
 if stolmax is not None:
  stol=np.asarray(d.GetSinThetaOverLambda())[:len(f0)];sel=sel[stol<=stolmax]
  n=min(n,int(np.searchsorted(x,2*np.arcsin(stolmax*p.GetWavelength())+np.deg2rad(p.GetPar('Zero').GetHumanValue()))))
