for nm in ['U','V','W','X','G_HH','G_KK','G_LL','Eta0','Eta1','Asym0','Asym1']:
 try:lsq.SetParIsFixed(nm,False)
 except Exception as e:print('PAR',nm,e,flush=True)
for i in range(int(os.getenv('ANISO_CYCLES','6'))):
