 def calc(t,detail=False):
  ds=[]
  for el in els:
   D=L.get_all_distances(fa[ea==el],fb[eb==el]+t);i,j=linear_sum_assignment(D**2);ds.extend(D[i,j])
  return (np.sqrt(np.mean(np.array(ds)**2)),max(ds)) if detail else sum(np.array(ds)**2)
